# The documentation site: docs\*.md -> site\docs\**.html, generated by src\tools\docsite, which then checks that every internal link and anchor in the generated pages resolves. The generation is
# deterministic (same docs, _nav.txt and git history -> same bytes), so -Check verifies site\docs is up to date without writing, the way tools\changelog.ps1 -Check does.
#
#   powershell -File tools\docs_site.ps1            build docsite if needed, regenerate site\docs, then check links
#   powershell -File tools\docs_site.ps1 -Check     write nothing; fail if site\docs is stale or any link/anchor is dead (CI)
#   powershell -File tools\docs_site.ps1 -NoBuild   skip rebuilding docsite.exe (use the existing one)
#
# Exit code 0 when all is well, 1 otherwise.
param(
    [switch]$Check,
    [switch]$NoBuild,
    [switch]$ChartUpdate   # rebuild docs\_wpt_history.tsv from the full git history (at a release)
)
$ErrorActionPreference = 'Stop'
$Root = Split-Path $PSScriptRoot -Parent
Push-Location $Root
try {
    $exe = Join-Path $Root 'build\docsite.exe'

    # Build the generator unless asked not to, or when it is missing or older than its sources.
    if (-not $NoBuild) {
        $need = -not (Test-Path $exe)
        if (-not $need) {
            $built = (Get-Item $exe).LastWriteTimeUtc
            $need = @(Get-ChildItem 'src\tools\docsite' -Filter *.odin | Where-Object { $_.LastWriteTimeUtc -gt $built }).Count -gt 0
        }
        if ($need) {
            New-Item -ItemType Directory -Force (Join-Path $Root 'build') | Out-Null
            cmd /c "odin build src/tools/docsite -collection:wb=src -vet -out:build/docsite.exe 2>&1" | Out-Host
            if ($LASTEXITCODE) { Write-Error 'docs_site: docsite did not build'; exit 1 }
        }
    }
    if (-not (Test-Path $exe)) { Write-Error 'docs_site: build\docsite.exe is missing (run without -NoBuild)'; exit 1 }

    # Generate (or verify the output is current), and check the links.
    $argList = @()
    if ($Check) { $argList += '-check' }
    if ($ChartUpdate) { $argList += '-chart-update' }
    & $exe @argList
    if ($LASTEXITCODE) {
        if ($Check) { Write-Error 'docs_site: site\docs is out of date, or a link is dead (run tools\docs_site.ps1)' }
        else { Write-Error 'docs_site: generation failed, or a link is dead' }
        exit 1
    }
    exit 0
}
finally {
    Pop-Location
}
